={{ 
(() => {
  const base = "http://192.168.56.1:8000";

  const index = $json.result?.index_name || "pc1";
  const alert_name = $json.result?.alert_name || "";

  const host = $json.result?.dest_host || $json.result?.ComputerName || "";
  const src_ip = $json.result?.src_ip || "";
  const dest_ip = $json.result?.dest_ip || "";

  const filename = $json.result?.filename || "";
  let file_path = $json.result?.file_created || "";

  const process = $json.result?.process || $json.result?.process_name || "";
  const commandLine = $json.result?.CommandLine || "";

  const transaction_id = $json.result?.transaction_id || "";

  const event_id = String($json.result?.event_id || "");
  const user = $json.result?.user || "";
  const logon_type = $json.result?.logon_type || "";

  const parent_process = $json.result?.parent_process_name || "";
  const child_process = $json.result?.process_name || "";

  const src_port = $json.result?.SourcePort || "";
  const dest_port = $json.result?.DestinationPort || "";

  if (file_path) {
    file_path = file_path.replace(/\\/g, "\\\\");
  }

  let epoch = $json.result?._time
    ? Math.floor(parseFloat($json.result._time))
    : Math.floor(Date.now() / 1000);

  const earliest = epoch - 600;
  const latest = epoch + 120;

  let filter = "";

  // =========================
  // ✅ WAF LOGIC
  // =========================
  if (index === "waf") {

    if (transaction_id) {
      filter = `sourcetype=modsecurity:json transaction.transaction_id="${transaction_id}"`;
    } else if (src_ip) {
      filter = `sourcetype=modsecurity:json transaction.remote_address="${src_ip}"`;
    } else {
      filter = `sourcetype=modsecurity:json`;
    }

  // =========================
  // 🔥 BRUTE FORCE ALERT
  // =========================
  } else if (alert_name.includes("Brute Force")) {

    const win = `sourcetype=WinEventLog`;
    let conditions = [`EventCode=4625`];

    if (host) conditions.push(`host="${host}"`);

    if (user) {
      conditions.push(`(Account_Name="*${user}*" OR TargetUserName="*${user}*")`);
    }

    if (src_ip) conditions.push(`Source_Network_Address="${src_ip}"`);
    if (logon_type) conditions.push(`Logon_Type="${logon_type}"`);

    filter = `${win} ${conditions.join(" ")}`;

  // =========================
  // 🔥 SUSPICIOUS POWERSHELL FLAGS
  // =========================
  } else if (alert_name.includes("PowerShell Flags")) {

    const sysmon = `sourcetype=WinEventLog LogName="Microsoft-Windows-Sysmon/Operational"`;
    let conditions = [`EventCode=1`, `Image="*powershell.exe*"`];

    if (host) conditions.push(`host="${host}"`);
    if (user) conditions.push(`User="*${user}*"`);

    if (commandLine) {
      const cmd = commandLine.toLowerCase();
      let flagConditions = [];

      if (cmd.includes("-enc")) flagConditions.push('CommandLine="*-enc*"');
      if (cmd.includes("-nop")) flagConditions.push('CommandLine="*-nop*"');
      if (cmd.includes("-w hidden") || cmd.includes("-windowstyle hidden")) {
        flagConditions.push('CommandLine="*hidden*"');
      }
      if (cmd.includes("-ep bypass") || cmd.includes("-executionpolicy bypass")) {
        flagConditions.push('CommandLine="*bypass*"');
      }
      if (cmd.includes("-noni")) flagConditions.push('CommandLine="*-noni*"');

      if (flagConditions.length > 0) {
        conditions.push(`(${flagConditions.join(" OR ")})`);
      }
    }

    filter = `${sysmon} ${conditions.join(" ")}`;

  // =========================
  // 🔥 SUSPICIOUS PARENT-CHILD PROCESS
  // =========================
  } else if (alert_name.includes("Parent-Child")) {

    const sysmon = `sourcetype=WinEventLog LogName="Microsoft-Windows-Sysmon/Operational"`;
    let conditions = [`EventCode=1`];

    if (host) conditions.push(`host="${host}"`);
    if (user) conditions.push(`User="*${user}*"`);

    if (parent_process) {
      const parentExe = parent_process.split("\\").pop();
      conditions.push(`ParentImage="*${parentExe}*"`);
    }

    if (child_process) {
      const childExe = child_process.split("\\").pop();
      conditions.push(`Image="*${childExe}*"`);
    }

    filter = `${sysmon} ${conditions.join(" ")}`;

  // =========================
  // 🔥 NETWORK CONNECTION FROM SUSPICIOUS PROCESS
  // =========================
  } else if (alert_name.includes("Suspicious Process") && alert_name.includes("Network")) {

    const sysmon = `sourcetype=WinEventLog LogName="Microsoft-Windows-Sysmon/Operational"`;
    let conditions = [`EventCode=3`];

    if (host) conditions.push(`host="${host}"`);
    if (user) conditions.push(`User="*${user}*"`);

    if (dest_ip) conditions.push(`DestinationIp="${dest_ip}"`);
    if (dest_port) conditions.push(`DestinationPort="${dest_port}"`);

    if (process) {
      const procName = process.split("\\").pop();
      conditions.push(`Image="*${procName}*"`);
    }

    filter = `${sysmon} ${conditions.join(" ")}`;

  // =========================
  // 🔥 CREDENTIAL DUMPING TOOL EXECUTION
  // =========================
  } else if (alert_name.includes("Credential Dumping")) {

    const sysmon = `sourcetype=WinEventLog LogName="Microsoft-Windows-Sysmon/Operational"`;
    let conditions = [`EventCode=1`];

    if (host) conditions.push(`host="${host}"`);
    if (user) conditions.push(`User="*${user}*"`);

    if (process) {
      const procName = process.split("\\").pop();
      conditions.push(`Image="*${procName}*"`);
    }

    if (commandLine) {
      const cmd = commandLine.toLowerCase();
      let cmdConditions = [];

      if (cmd.includes("sekurlsa")) {
        cmdConditions.push(`CommandLine="*sekurlsa*"`);
      }

      if (cmd.includes("logonpasswords")) {
        cmdConditions.push(`CommandLine="*logonpasswords*"`);
      }

      if (cmdConditions.length > 0) {
        conditions.push(`(${cmdConditions.join(" OR ")})`);
      }
    }

    if (parent_process) {
      const parentExe = parent_process.split("\\").pop();
      conditions.push(`ParentImage="*${parentExe}*"`);
    }

    filter = `${sysmon} ${conditions.join(" ")}`;

  // =========================
  // ✅ WINDOWS EVENT LOGS
  // =========================
  } else if (["4624", "4625"].includes(event_id)) {

    const win = `sourcetype=WinEventLog`;
    let baseFilter = `${win} EventCode=${event_id}`;

    if (host) baseFilter += ` host="${host}"`;

    if (user) {
      baseFilter += ` (Account_Name="*${user}*" OR TargetUserName="*${user}*")`;
    }

    filter = baseFilter;

  // =========================
  // ✅ SYSMON LOGIC
  // =========================
  } else {

    const sysmon = `sourcetype=WinEventLog LogName="Microsoft-Windows-Sysmon/Operational"`;

    // 🔴 File Creation
    if (alert_name.includes("File Creation") || alert_name.includes("Archive")) {

      const baseFilter = `${sysmon} EventCode=11`;

      if (file_path) {
        filter = `${baseFilter} TargetFilename="${file_path}"`;
      } else if (filename) {
        filter = `${baseFilter} TargetFilename="*${filename}"`;
      } else {
        filter = `${baseFilter} host="${host}"`;
      }

    // 🟡 Process Execution (GENERIC FALLBACK)
    } else if (
      alert_name.includes("Process Execution") ||
      alert_name.includes("Recon") ||
      alert_name.includes("Tool")
    ) {

      const baseFilter = `${sysmon} EventCode=1`;
      const normalizedCmd = commandLine.toLowerCase();

      if (alert_name.includes("Recon") && normalizedCmd) {

        const commands = normalizedCmd
          .split("|")
          .map(cmd => cmd.trim())
          .filter(cmd => cmd.length > 0)
          .map(cmd => {
            cmd = cmd.replace(/"/g, "");
            let exe = cmd.split("\\").pop();
            exe = exe.split(" ")[0];
            return exe;
          });

        const uniqueCommands = [...new Set(commands)];

        const orConditions = uniqueCommands
          .map(cmd => `Image="*${cmd}*"`)
          .join(" OR ");

        filter = `${baseFilter} (${orConditions})`;

      } else if (process) {
        const procName = process.split("\\").pop();
        let conditions = [`Image="*${procName}*"`];

        if (user) conditions.push(`User="*${user}*"`);

        filter = `${baseFilter} ${conditions.join(" ")}`;

      } else if (normalizedCmd) {
        const safeCmd = normalizedCmd.replace(/"/g, '').substring(0, 50);
        filter = `${baseFilter} CommandLine="*${safeCmd}*"`;

      } else {
        filter = `${baseFilter} host="${host}"`;
      }

    // 🔵 Network / Exfil (GENERIC FALLBACK)
    } else if (
      alert_name.includes("Outbound") ||
      alert_name.includes("Exfil")
    ) {

      const baseFilter = `${sysmon} EventCode=3`;
      let conditions = [];

      if (dest_ip) conditions.push(`DestinationIp="${dest_ip}"`);

      if (process) {
        const procName = process.split("\\").pop();
        conditions.push(`Image="*${procName}*"`);
      }

      if (user) conditions.push(`User="*${user}*"`);

      if (conditions.length > 0) {
        filter = `${baseFilter} ${conditions.join(" ")}`;
      } else if (host) {
        filter = `${baseFilter} host="${host}"`;
      } else {
        filter = `${baseFilter}`;
      }

    } else {
      filter = `${sysmon} host="${host}"`;
    }
  }

  const query = `search index=${index} ${filter}`;
  return `${base}/en-US/app/search/search?q=${query}&earliest=${earliest}&latest=${latest}`;
})()
}}

parameters.jsCode:
const original = $item(0).$node["Normalize Alert"].json;
const vt = $json;

// If VT failed or empty
if (!vt || Object.keys(vt).length === 0 || vt.vt_score === undefined) {
  return [
    {
      json: {
        ...original,
        vt_score: 0,
        vt_label: "unavailable",
        file_name: ""
      }
    }
  ];
}

// If VT success
return [
  {
    json: {
      ...original,
      vt_score: vt.vt_score || 0,
      vt_label: vt.vt_label || "unknown",
      file_name: vt.file_name || "",
      severity: vt.verdict === "malicious"
        ? "critical"
        : original.severity,
      risk_score: vt.verdict === "malicious"
        ? Math.min(original.risk_score + 50, 100)
        : original.risk_score
    }
  }
];

const alert = $item(0).$node["Alert + VT Enrichment"].json;
let socId = $json?.soc_id;

// 🚨 Fallback if SOC ID generator fails
if (!socId || socId === "" || socId === null) {
  socId = "SOC-TEMP-" + Date.now();

  // Optional: mark it for tracking
  alert.soc_id_fallback = true;
}

return [
  {
    json: {
      ...alert,
      alert_id: socId
    }
  }
];

